@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AddProfileDialog(
    onDismiss: () -> Unit,
    onSubmit: (name: String, kind: ProfileKind, phoneNumber: String?) -> Unit,
) {
    var name by remember { mutableStateOf("") }
    var kind by remember { mutableStateOf(ProfileKind.PERSON) }
    var phoneNumber by remember { mutableStateOf("") }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(stringResource(R.string.add_a_profile)) },
        text = {
            Column {
                OutlinedTextField(
                    value = name,
                    onValueChange = { name = it },
                    label = { Text(stringResource(R.string.name_label)) },
                    modifier = Modifier.fillMaxWidth(),
                )
                Row(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier.padding(top = 8.dp),
                ) {
                    FilterChip(
                        selected = kind == ProfileKind.PERSON,
                        onClick = { kind = ProfileKind.PERSON },
                        label = { Text(stringResource(R.string.person)) },
                        border = FilterChipDefaults.filterChipBorder(
                            enabled = true,
                            selected = kind == ProfileKind.PERSON,
                            borderColor = MaterialTheme.colorScheme.outline,
                            selectedBorderColor = IconOrange,
                            borderWidth = 1.dp,
                            selectedBorderWidth = 2.dp,
                        ),
                    )
                    FilterChip(
                        selected = kind == ProfileKind.PET,
                        onClick = { kind = ProfileKind.PET },
                        label = { Text(stringResource(R.string.pet)) },
                        border = FilterChipDefaults.filterChipBorder(
                            enabled = true,
                            selected = kind == ProfileKind.PET,
                            borderColor = MaterialTheme.colorScheme.outline,
                            selectedBorderColor = IconOrange,
                            borderWidth = 1.dp,
                            selectedBorderWidth = 2.dp,
                        ),
                    )
                }
                OutlinedTextField(
                    value = phoneNumber,
                    onValueChange = { phoneNumber = it },
                    label = { Text(stringResource(R.string.caregiver_phone_label)) },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 8.dp),
                )
            }
        },
        confirmButton = {
            TextButton(
                onClick = {
                    if (name.isNotBlank()) {
                        onSubmit(name, kind, phoneNumber.ifBlank { null })
                    }
                },
            ) {
                Text(stringResource(R.string.add))
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text(stringResource(R.string.cancel)) }
        },
    )
}
